# Local configuration and client helper utilities for Static Image and Visual Understanding\nimport os\n\nclass VisionClient:\n    \"\"\"Shared helpers for instantiating external provider clients.\n    Provides concrete client factories identified by the provider used.\n    \"\"\"\n    @staticmethod\n    def get_clarifai_client():\n        \"\"\"Return a Clarifai client configured via CLARIFAI_PAT environment variable.\n        \"\"\"\n        from clarifai.rest import Clarifi\n        api_key = os.getenv(\"CLARIFAI_PAT\")\n        if not api_key:\n            raise RuntimeError(\"CLARIFAI_PAT environment variable not set\")\n        return Clarifi(api_key=api_key)\n\n    @staticmethod\n    def get_anthropic_client():\n        \"\"\"Return an Anthropic client configured via ANTHROPIC_API_KEY.\n        \"\"\"\n        from anthropic import Anthropic\n        api_key = os.getenv(\"ANTHROPIC_API_KEY\")\n        if not api_key:\n            raise RuntimeError(\"ANTHROPIC_API_KEY environment variable not set\")\n        return Anthropic(api_key=api_key)\n\n    @staticmethod\n    def get_vision_azure_client():\n        \"\"\"Return an Azure Vision client using AZURE_VISION_ENDPOINT and AZURE_VISION_KEY.\n        \"\"\"\n        from azure.ai.vision import VisionClient as AzVisionClient\n        from azure.core.credentials import AzureKeyCredential\n        endpoint = os.getenv(\"AZURE_VISION_ENDPOINT\")\n        key = os.getenv(\"AZURE_VISION_KEY\")\n        if not endpoint or not key:\n            raise RuntimeError(\"AZURE_VISION_ENDPOINT and AZURE_VISION_KEY must be set\")\n        return AzVisionClient(credential=AzureKeyCredential(key), endpoint=endpoint)\n\n    @staticmethod\n    def get_bedrock_client():\n        \"\"\"Return a Bedrock client for safety checks using AWS credentials.\n        \"\"\"\n        import boto3\n        return boto3.client(\"bedrock-runtime\", region_name=\"us-east-1\")\n\n    # Additional provider factories can be added here following the same pattern\n# -----------------------------------------------------------------------------\n# End of vision_client.py – no further code required for the current set of files\n# -----------------------------------------------------------------------------
